func (st *ReviewStore) ListByProduct(productID string) []Review {
	st.mu.RLock()
	defer st.mu.RUnlock()
	out := []Review{}
	for _, rv := range st.items {
		if rv.ProductID == productID {
			out = append(out, rv)
		}
	}
	slices.SortFunc(out, func(a, b Review) int { return strings.Compare(a.ID, b.ID) })
	return out
}
