		review   Review
		id      string
		expected bool
	}{
		{name: "returns true for existing ID", review: Review{ID: "", ProductID: "", UserID: "", Rating: 5, Body: ""}, id: "rev_000001", expected: true},
		{name: "returns false for missing ID", review: Review{ID: "", ProductID: "", UserID: "", Rating: 5, Body: ""}, id: "rev_999999", expected: false},
	}
