func TestReviewStore_ListByProduct_WithReviews(t *testing.T) {
	store := NewReviewStore()
	reviews := []Review{
		{ID: "rev_000003", ProductID: "prod_000000", UserID: "", Rating: 3, Body: ""},
		{ID: "rev_000001", ProductID: "prod_000000", UserID: "", Rating: 5, Body: ""},
